<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { Send, RotateCw, ExternalLink, Copy, ChevronDown, ChevronRight } from '@lucide/vue';
import type { DeliveryTask } from '../../../shared/task-presentation';
import { api, platform, message } from '../api';
import { notify } from '../lib/notifications';
import Disclosure from './Disclosure.vue';
import TablePagination from './TablePagination.vue';
const props=defineProps<{task:DeliveryTask;canDeliver?:boolean;canForceDeliver?:boolean;forceDeliverReason?:string;canForceRetry?:boolean}>();const emit=defineEmits<{changed:[]}>();
const busy=ref(false),error=ref(''),targetId=ref(''),targetUrl=ref('');
const confirmForceDeliver=ref(false),confirmForceRetry=ref(false);
const enabled=computed(()=>platform.settings?.environments.find(e=>e.id===props.task.environmentId)?.delivery?.enabled);
const envVerifyWithAi=computed(()=>platform.settings?.environments.find(e=>e.id===props.task.environmentId)?.delivery?.verifyWithAi!==false);
const names={queued:'等待交付',running:'迁移中',uncertain:'迁移结果待核查',verifying:'交付核验中',completed:'交付核验完成',failed:'交付未完成'};
const evidenceOpen=ref(false),evidencePage=ref(1);
const images=computed(()=>props.task.delivery?.artifacts?.filter(f=>f.type==='image/png')||[]);
const evidencePages=computed(()=>Math.max(1,Math.ceil(images.value.length/12)));
const visibleImages=computed(()=>images.value.slice((evidencePage.value-1)*12,evidencePage.value*12));
const showNormalDeliver=computed(()=>!props.task.delivery&&(props.canDeliver??(props.task.status==='completed'&&(props.task.kind==='evaluation'?Boolean(props.task.report):true))));
const showForceDeliver=computed(()=>!props.task.delivery&&!showNormalDeliver.value&&Boolean(props.canForceDeliver));
const showForceRetry=computed(()=>Boolean(props.task.delivery&&!props.task.delivery.target&&['uncertain','failed'].includes(props.task.delivery.status)&&(props.canForceRetry??(props.task.delivery.stopped!==false&&(props.task.delivery.status==='uncertain'||Boolean(props.task.delivery.attemptedAt))))));
watch([()=>props.task.id,()=>props.task.delivery?.status],()=>{confirmForceDeliver.value=false;confirmForceRetry.value=false;});
async function copyUrl(url:string){try{await navigator.clipboard.writeText(url);notify.success('已复制交付地址');}catch{notify.error('无法访问剪贴板，请手动复制');}}
async function action(suffix='',body?:unknown){busy.value=true;error.value='';try{const forced=Boolean((body as {force?:boolean}|undefined)?.force);await api(`/automation/tasks/${props.task.id}/delivery${suffix}`,{method:'POST',...(body?{body:JSON.stringify(body)}:{})});confirmForceDeliver.value=false;confirmForceRetry.value=false;notify.success(suffix==='/receipt'?'回执已保存，已排队核验':suffix==='/cancel'?'已请求停止交付':suffix==='/confirm-stopped'?'已确认停止，可恢复核验':suffix==='/retry'?(forced?'已强制重发跨环境迁移':'已排队重试迁移准备'):forced?'已排队强制跨环境交付':'已排队交付核验');emit('changed');}catch(e){error.value=message(e);}finally{busy.value=false;}}
</script>
<template><section v-if="(task.kind==='evaluation'||task.kind==='generation')&&(enabled||task.delivery)" class="panel settings-panel delivery-panel"><div class="section-heading"><h2>跨环境交付</h2><button v-if="showNormalDeliver" class="button secondary small" :disabled="busy" @click="action()"><Send :size="15"/>{{envVerifyWithAi?'迁移并核验':'迁移并交付'}}</button><button v-else-if="showForceDeliver" class="button secondary small" :disabled="busy" @click="confirmForceDeliver=true"><Send :size="15"/>强制交付</button></div><div v-if="showForceDeliver&&confirmForceDeliver" class="force-confirm-box" role="region" aria-label="确认强制交付"><p>{{forceDeliverReason||'当前任务尚未完成或未通过评测门禁。'}}请确认已打开源站完成初步验收；强制交付将直接迁移当前源站，源站保留不变。</p><div class="inline-actions"><button type="button" class="button primary small" :disabled="busy" @click="action('',{force:true})">确认强制交付</button><button type="button" class="button secondary small" :disabled="busy" @click="confirmForceDeliver=false">取消</button></div></div><template v-if="task.delivery"><div class="inline-actions"><strong>{{names[task.delivery.status]}}</strong><span v-if="task.delivery.forced" class="force-delivery-tag">人工强制交付</span><button v-if="task.delivery.status==='failed'&&!task.delivery.target&&!task.delivery.attemptedAt" class="button secondary small" :disabled="busy" @click="action('/retry')">重试迁移准备</button><button v-if="task.delivery.stopped!==false&&task.delivery.target&&['failed','completed'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/verify')"><RotateCw :size="14"/>{{task.delivery.policy.verifyWithAi===false?'重新检查可达性':'恢复 / 重新核验'}}</button><button v-if="['queued','running','verifying'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/cancel')">停止交付</button></div><div v-if="task.delivery.target" class="delivery-links-box"><div class="delivery-link-row" :class="{'delivery-link-primary':task.delivery.status==='completed'}"><span class="delivery-link-label">{{task.delivery.status==='completed'?'交付地址（主链接）':'目标站地址'}}</span><a class="delivery-link-url" :href="task.delivery.target.siteUrl" target="_blank" rel="noopener noreferrer">{{task.delivery.target.siteUrl}}<ExternalLink :size="14"/></a><button type="button" class="icon-button" aria-label="复制交付地址" title="复制交付地址" @click="copyUrl(task.delivery.target.siteUrl)"><Copy :size="15"/></button></div><div v-if="task.delivery.sourceUrl&&task.delivery.sourceUrl!==task.delivery.target.siteUrl" class="delivery-link-row delivery-link-secondary"><span class="delivery-link-label">源站地址</span><a class="delivery-link-url" :href="task.delivery.sourceUrl" target="_blank" rel="noopener noreferrer">{{task.delivery.sourceUrl}}<ExternalLink :size="12"/></a></div></div><button v-if="task.delivery.stopped===false&&['failed','uncertain'].includes(task.delivery.status)" class="button secondary small" :disabled="busy" @click="action('/confirm-stopped')">已检查原浏览器，确认交付执行停止</button><p v-if="task.delivery.error" class="alert info">{{task.delivery.error}}</p><div v-if="!task.delivery.target&&['uncertain','failed'].includes(task.delivery.status)" class="delivery-receipt"><p>在目标环境或迁移服务核查实际结果后，补录已创建站点的回执；系统会确认目标身份并继续核验。</p><div class="form-grid"><label class="field"><span>目标 Site ID</span><input v-model="targetId" class="input"/></label><label class="field"><span>目标站 URL</span><input v-model="targetUrl" class="input" type="url"/></label></div><button class="button secondary small" :disabled="busy||!targetId||!targetUrl" @click="action('/receipt',{siteId:targetId,siteUrl:targetUrl})">保存回执并核验</button><div v-if="showForceRetry" class="delivery-force-retry"><p class="text-muted">若已在目标环境核查确认未生成目标站，可手动强制重发迁移请求：</p><button v-if="!confirmForceRetry" type="button" class="button secondary small" :disabled="busy" @click="confirmForceRetry=true">已核查未建站，强制重发</button><div v-else class="force-confirm-box" role="region" aria-label="确认强制重发"><p>请务必先核查目标环境确认尚未建站，否则强行重发可能创建重复站点。</p><div class="inline-actions"><button type="button" class="button primary small" :disabled="busy" @click="action('/retry',{force:true})">确认强制重发</button><button type="button" class="button secondary small" :disabled="busy" @click="confirmForceRetry=false">取消</button></div></div></div></div><p v-if="task.delivery.status==='completed'&&!task.delivery.verification&&task.delivery.policy.verifyWithAi===false" class="text-muted">已关闭 AI 视觉核验：站点已迁移至目标环境并通过 HTTP 可达性检查。</p><div v-if="task.delivery.verification"><p>{{task.delivery.verification.summary}}</p><div class="coverage-grid"><div><h3>已验证</h3><ul><li v-for="text in task.delivery.verification.verified" :key="text">{{text}}</li></ul></div><div><h3>未验证 / 未通过</h3><ul><li v-for="text in task.delivery.verification.unverified" :key="text">{{text}}</li></ul></div></div><button class="text-action" :aria-expanded="evidenceOpen" @click="evidenceOpen=!evidenceOpen"><ChevronDown v-if="evidenceOpen" :size="16"/><ChevronRight v-else :size="16"/>查看核验证据（{{images.length}}）</button><template v-if="evidenceOpen"><div class="evidence-grid"><a v-for="file in visibleImages" :key="file.id" :href="`/api/v1/automation/reports/${task.id}/delivery/artifacts/${file.name}`" target="_blank"><img :src="`/api/v1/automation/reports/${task.id}/delivery/artifacts/${file.name}`" loading="lazy" :alt="`交付核验证据 ${file.name}`"/></a></div><TablePagination :page="evidencePage" :pages="evidencePages" :total="images.length" @change="evidencePage=$event"/></template></div><Disclosure v-if="task.delivery.checks.length" label="访问检查"><p v-for="check in task.delivery.checks" :key="check.url">{{check.ok?'通过':'未通过'}} · {{check.url}} · {{check.detail}}</p></Disclosure></template><p v-else class="text-muted">{{showForceDeliver?(forceDeliverReason||'当前任务未完成或未通过门禁，可在完成初步验收后点击右上角「强制交付」。'):task.kind==='generation'?'站点已生成，可直接发起跨环境交付；保留源站。':'完成源环境评测后可发起交付；迁移及核验独立记录，保留源站报告。'}}</p><p v-if="error" class="alert error">{{error}}</p></section></template>

<style scoped>
.delivery-panel{display:flex;flex-direction:column;gap:16px}.delivery-panel .section-heading,.delivery-panel .inline-actions,.delivery-panel h2{margin:0}.delivery-panel .inline-actions{flex-wrap:wrap}.delivery-receipt{display:flex;flex-direction:column;gap:16px}
.force-confirm-box{display:flex;flex-direction:column;gap:10px;padding:12px 14px;border-radius:10px;background:#fffaf2;border:1px solid #f0d7a8;color:#6e4714;font-size:13px}
.force-confirm-box p{margin:0;line-height:1.5}
.force-delivery-tag{display:inline-flex;align-items:center;padding:2px 8px;border-radius:999px;background:#fff4e5;color:#995608;font-size:11.5px;font-weight:600}
.delivery-force-retry{display:flex;flex-direction:column;gap:10px;padding-top:12px;border-top:1px solid var(--line)}
.delivery-force-retry>p{margin:0;font-size:12.5px}
.delivery-links-box{display:flex;flex-direction:column;gap:8px;padding:12px 14px;background:var(--field);border:1px solid #e3e8f2;border-radius:10px}
.delivery-link-row{display:flex;align-items:center;flex-wrap:wrap;gap:8px 10px;min-width:0;font-size:13px}
.delivery-link-label{color:var(--muted);font-size:12px;white-space:nowrap}
.delivery-link-url{display:inline-flex;align-items:center;gap:5px;min-width:0;max-width:100%;color:var(--blue);font-weight:500;overflow-wrap:anywhere}
.delivery-link-primary .delivery-link-url{color:#16765d;font-weight:600}
.delivery-link-secondary{font-size:12px}
.delivery-link-secondary .delivery-link-url{color:var(--muted);font-weight:400}
.delivery-link-url:hover{text-decoration:underline}
</style>
